import{V as t,W as c}from"./index-DLlmPWom.js";const y={async listCases(s={}){return t(`/cases${c(s)}`)},async getCase(s){return t(`/cases/${s}`)},async createCase(s){return t("/cases",{method:"POST",body:JSON.stringify(s)})},async updateCase(s,e){return t(`/cases/${s}`,{method:"PATCH",body:JSON.stringify(e)})},async deleteCase(s){await t(`/cases/${s}`,{method:"DELETE"})},async changeStatus(s,e,a,n,r){return t(`/cases/${s}/status`,{method:"POST",body:JSON.stringify({to_status:e,note:a,resolution_outcome:n,resolution_summary:r})})},async assign(s,e,a){return t(`/cases/${s}/assign`,{method:"POST",body:JSON.stringify({assignee_id:e,note:a})})},async addNote(s,e){return t(`/cases/${s}/notes`,{method:"POST",body:JSON.stringify({body:e})})},async escalate(s,e){return t(`/cases/${s}/escalate`,{method:"POST",body:JSON.stringify(e)})},async resolve(s,e){return t(`/cases/${s}/resolve`,{method:"POST",body:JSON.stringify(e)})},async linkEntity(s,e,a){return t(`/cases/${s}/entities`,{method:"POST",body:JSON.stringify({entity_id:e,role:a})})},async listAssignableUsers(){return t("/users/assignable")},async getWorkflow(){return t("/cases/workflow")}};export{y as caseService};
